/**
 * Bundled game data (generated by /scripts, version-controlled JSON) and lookups.
 * Piece geometry and the world background are lazy-loaded separately (see src/map/geodata.ts).
 */
import countriesJson from './countries.json';
import citiesJson from './cities.json';
import facts from './country-facts.json';
import { buildNameIndex, type NameIndex } from '../game/matching';
import type { City, Country, Mode, Target } from '../game/types';

export const COUNTRIES: Country[] = (countriesJson as unknown as Country[]).map((c) => ({
  ...c,
  fact: (facts as Record<string, string>)[c.id],
}));
export const CITIES: City[] = citiesJson as unknown as City[];

export const countryById = new Map(COUNTRIES.map((c) => [c.id, c]));
export const cityById = new Map(CITIES.map((c) => [c.id, c]));

export { CONTINENTS } from './continents';

const countryTargets: Target[] = COUNTRIES.map((c) => ({
  id: c.id,
  name: c.name,
  altNames: c.altNames,
  rank: c.rank,
  continent: c.continents[0],
}));

const cityTargets: Target[] = CITIES.map((c) => {
  const country = countryById.get(c.country)!;
  return {
    id: c.id,
    name: c.name,
    altNames: c.altNames,
    rank: c.rank,
    qualifier: country.name,
    continent: country.continents[0],
  };
});

export const TARGETS: Record<Mode, Target[]> = { countries: countryTargets, cities: cityTargets };

const indexCache: Partial<Record<Mode, NameIndex>> = {};
export function nameIndex(mode: Mode): NameIndex {
  return (indexCache[mode] ??= buildNameIndex(TARGETS[mode]));
}

/** Country that a target belongs to (the target itself in country mode). */
export function countryOfTarget(mode: Mode, id: string): Country | undefined {
  if (mode === 'countries') return countryById.get(id);
  const city = cityById.get(id);
  return city ? countryById.get(city.country) : undefined;
}

export function targetName(mode: Mode, id: string): string {
  return mode === 'countries' ? (countryById.get(id)?.name ?? id) : (cityById.get(id)?.name ?? id);
}
